import React, { useState, useEffect } from 'react';

// Dummy API functions (replace with actual API calls)
const getContacts = async () => {
  // Simulate API call
  return { data: [{ name: 'John Doe', phone: '123-456-7890', email: 'john@example.com', address: '123 Main St' }] };
};

const addContact = async (contact) => {
  // Simulate API call to add contact
  return contact;
};

const updateContact = async (index, contact) => {
  // Simulate API call to update contact
  return { ...contact, name: 'Updated ' + contact.name };
};

const deleteContact = async (index) => {
  // Simulate API call to delete contact
  return index;
};

function App() {
  const [contacts, setContacts] = useState([]);  // Initialize contacts as an empty array
  const [loading, setLoading] = useState(true);   // Add loading state
  const [newContact, setNewContact] = useState({ name: '', phone: '', email: '', address: '' }); // Add state for new contact form

  // Fetch contacts when the component mounts
  useEffect(() => {
    const fetchContacts = async () => {
      try {
        const response = await getContacts();
        setContacts(response.data); // Update state with fetched contacts
        setLoading(false); // Data has finished loading
      } catch (error) {
        console.error('There was an error fetching contacts:', error);
        setLoading(false); // Stop loading even in case of error
      }
    };

    fetchContacts();
  }, []);  // Empty dependency array ensures this effect runs only once

  if (loading) {
    return <div>Loading...</div>; // Show loading state while fetching data
  }

  const handleAddContact = () => {
    if (newContact.name && newContact.phone && newContact.email && newContact.address) {
      addContact(newContact).then((createdContact) => {
        setContacts([...contacts, createdContact]);
        setNewContact({ name: '', phone: '', email: '', address: '' }); // Reset form after adding
      });
    } else {
      alert('Please fill in all fields.');
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewContact({ ...newContact, [name]: value });  // Update the specific field in the form state
  };

  const handleUpdateContact = (index, contact) => {
    updateContact(index, contact).then((updatedContact) => {
      const updatedContacts = contacts.map((c, i) =>
        i === index ? updatedContact : c
      );
      setContacts(updatedContacts);
    });
  };

  const handleDeleteContact = (index) => {
    deleteContact(index).then(() => {
      const updatedContacts = contacts.filter((_, i) => i !== index);
      setContacts(updatedContacts);
    });
  };

  return (
    <div>
      <h1>Contacts</h1>
      <ul>
        {contacts.map((contact, index) => (
          <li key={index}>
            {contact.name} - {contact.phone} - {contact.email} - {contact.address}
            <button onClick={() => handleUpdateContact(index, contact)}>Update</button>
            <button onClick={() => handleDeleteContact(index)}>Delete</button>
          </li>
        ))}
      </ul>

      {/* Form to Add a New Contact */}
      <div>
        <h2>Add New Contact</h2>
        <form onSubmit={(e) => e.preventDefault()}>
          <input
            type="text"
            name="name"
            value={newContact.name}
            onChange={handleInputChange}
            placeholder="Name"
          />
          <input
            type="text"
            name="phone"
            value={newContact.phone}
            onChange={handleInputChange}
            placeholder="Phone"
          />
          <input
            type="email"
            name="email"
            value={newContact.email}
            onChange={handleInputChange}
            placeholder="Email"
          />
          <input
            type="text"
            name="address"
            value={newContact.address}
            onChange={handleInputChange}
            placeholder="Address"
          />
          <button type="button" onClick={handleAddContact}>Add Contact</button>
        </form>
      </div>
    </div>
  );
}

export default App;
